class Solution {
    /**
     * @param {string} s
     * @return {string}
     */
    frequencySort(s) {
        const count = {};
        for (const char of s) {
            count[char] = (count[char] || 0) + 1;
        }

        const sortedChars = [...s].sort((a, b) => {
            if (count[b] === count[a]) {
                return a.localeCompare(b);
            }
            return count[b] - count[a];
        });

        return sortedChars.join('');
    }
}
