impl Solution {
    pub fn frequency_sort(s: String) -> String {
        let mut count = [0i32; 123];
        for b in s.bytes() {
            count[b as usize] += 1;
        }

        let mut chars: Vec<u8> = s.into_bytes();
        chars.sort_by(|&a, &b| {
            if count[b as usize] == count[a as usize] {
                a.cmp(&b)
            } else {
                count[b as usize].cmp(&count[a as usize])
            }
        });

        String::from_utf8(chars).unwrap()
    }
}
