impl Solution {
    pub fn frequency_sort(s: String) -> String {
        let mut count = HashMap::new();
        for b in s.bytes() {
            *count.entry(b).or_insert(0) += 1;
        }

        let n = s.len();
        let mut buckets = vec![vec![]; n + 1];
        for (&ch, &freq) in &count {
            buckets[freq as usize].push(ch);
